'use client'

import React, { useState, useEffect } from 'react'
import { X, ArrowRight } from 'lucide-react'
import { createPortal } from 'react-dom'

interface ApplicationModalProps {
    formUrl: string
    isOpen: boolean
    onClose: () => void
}

export default function ApplicationModal({ formUrl, isOpen, onClose }: ApplicationModalProps) {
    const [mounted, setMounted] = useState(false)

    useEffect(() => {
        setMounted(true)
        if (isOpen) {
            document.body.style.overflow = 'hidden'
        } else {
            document.body.style.overflow = 'unset'
        }
        return () => {
            document.body.style.overflow = 'unset'
        }
    }, [isOpen])

    if (!mounted) return null

    return (
        <>
            {/* Fixed Apply Button */}
            <div className="fixed bottom-8 left-0 right-0 z-40 flex justify-center px-6 pointer-events-none">
                <button
                    onClick={() => setIsOpen(true)}
                    className="pointer-events-auto bg-[#c5a059] hover:bg-[#b08e4d] text-black font-serif font-bold py-3 px-8 rounded-full shadow-[0_0_20px_rgba(197,160,89,0.3)] hover:shadow-[0_0_30px_rgba(197,160,89,0.5)] transition-all duration-300 transform hover:scale-105 flex items-center gap-2 group"
                >
                    ỨNG TUYỂN NGAY
                    <ArrowRight className="w-5 h-5 transition-transform group-hover:translate-x-1" />
                </button>
            </div>

            {/* Modal Portal */}
            {isOpen && createPortal(
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-6">
                    {/* Backdrop */}
                    <div
                        className="absolute inset-0 bg-black/60 backdrop-blur-md transition-opacity"
                        onClick={() => setIsOpen(false)}
                    />

                    {/* Modal Content */}
                    <div className="relative w-full max-w-4xl h-[85vh] bg-[#1a1a1a]/90 border border-white/10 rounded-2xl shadow-2xl overflow-hidden flex flex-col animate-in fade-in zoom-in-95 duration-200">
                        {/* Header */}
                        <div className="flex items-center justify-between p-4 border-b border-white/5 bg-white/5 backdrop-blur">
                            <h3 className="text-[#c5a059] font-serif text-lg font-bold pl-2">
                                Đơn Ứng Tuyển
                            </h3>
                            <button
                                onClick={() => setIsOpen(false)}
                                className="p-2 text-gray-400 hover:text-white hover:bg-white/10 rounded-full transition-colors"
                            >
                                <X className="w-6 h-6" />
                            </button>
                        </div>

                        {/* Iframe Container with refined padding */}
                        <div className="flex-1 bg-white pt-8 pb-10 px-1">
                            <iframe
                                src={formUrl}
                                className="w-full h-full border-0"
                                title="Application Form"
                            />
                        </div>
                    </div>
                </div>,
                document.body
            )}
        </>
    )
}
